import json, sqlite3, sys
sys.path.insert(0, "/Users/stef/Projects/ehlcodacabana-final")
from buyer.economics import cost

REPO = "/Users/stef/Projects/ehlcodacabana-final"
cases = {c["case_id"]: c for c in json.load(open(f"{REPO}/logs/cases/practice.json"))}
db = sqlite3.connect(f"file:{REPO}/data/package/world.sqlite?mode=ro", uri=True)
db.row_factory = sqlite3.Row

QUOTE_FIELDS = ["unit_price", "payment_days", "lead_time_days", "incoterm", "tooling_eur"]

def latest_quote(case):
    sid, part = case["suppliers"][0], case["parts"][0]
    row = db.execute(
        "SELECT * FROM quotes WHERE supplier_id=? AND part_id=? ORDER BY quote_date DESC LIMIT 1", (sid, part)
    ).fetchone()
    q = dict(row)
    return {f: q[f] for f in QUOTE_FIELDS if q.get(f) is not None}, q["id"], q["quote_date"]

def show(cid):
    case = cases[cid]
    quote, qid, qdate = latest_quote(case)
    # quote's own terms as the term sheet; the same terms stand in for standard terms (approximation)
    terms = dict(quote)
    std = dict(quote)
    base = cost(case, terms, std)
    print(f"\n== {cid} {case['type']} goal={case['buyer']['category_goal']} quote {qid} {qdate} "
          f"unit_price={quote['unit_price']} base C={base:,.2f}")
    print(f"   negotiable={case['negotiable']}")
    rows = []
    for f in case["negotiable"]:
        if f == "unit_price":
            continue
        for o in case.get("term_options", {}).get(f, []):
            if f == "index_clause" and o is not None:
                label = f"{o['series']} share {o['material_share']} band {o['deadband_pct']}%"
            else:
                label = str(o)
            t = {**terms, f: o}
            c = cost(case, t, std)
            rows.append((c - base, f, label, c))
    # unit price sensitivity for reference: -1 % and +1 %
    for pct in (-1, 1):
        t = {**terms, "unit_price": round(quote["unit_price"] * (1 + pct / 100), 2)}
        c = cost(case, t, std)
        rows.append((c - base, "unit_price", f"{pct:+d}% price", c))
    for d, f, label, c in sorted(rows, key=lambda r: r[0]):
        print(f"   {f:18s} {label:38s} C={c:>14,.2f}  dC={d:>+14,.2f}")
    # also the quote-offered terms of the alternative
    alt = case["buyer"].get("alternative", {}).get("terms") or {}
    if alt.get("unit_price"):
        print(f"   [alternative C={cost(case, alt):,.2f}]")

for cid in ["case:P02", "case:P08", "case:P18", "case:P10", "case:P11"]:
    show(cid)
EOF
